import {
  getIdOrStringAccessor,
  getIsExcludableColumn,
  findColumnInstance,
} from './column-utils.js';
import type { ColumnMinInstance } from '../types/internal-table-types.js';
import type { TableColumn, ColumnGroup } from '../types/shared-table-types.js';
import { ColumnVisibilityConfig } from '../types/table-config-types.js';

/**
 * Creates a new object containing visibility status. Updates either one or
 * all entries with the new status. If you provide an `idOrAccessor` it updates
 * the one entry, otherwise it updates all entries with this status. Takes
 * account of updating sub-columns also. If a parent columns status is changed
 * then all sub-columns are also updated appropriately.
 * @param columnVisibility - existing column visibility settings
 * @param newVisibilityStatus - new setting
 * @param columns - table columns for purpose of finding sub-columns
 * @param idOrAccessor - if accessorOrId is not specified then all entries are changed
 *
 * @returns new object containing updated visibility status.
 */
export function getUpdatedVisibility(
  columnVisibility: ColumnVisibilityConfig,
  newVisibilityStatus: 'visible' | 'hidden',
  columns: ColumnMinInstance[],
  idOrAccessor?: string,
): ColumnVisibilityConfig {
  const result = { ...columnVisibility };
  const ids = idOrAccessor ? [idOrAccessor] : Object.keys(columnVisibility);

  for (const currentId of ids) {
    result[currentId] = newVisibilityStatus;
    // check / uncheck all sub-columns, if they exist:
    const matchingCol = findColumnInstance(columns, currentId);
    if (matchingCol) {
      const subCols = matchingCol?.columns;
      if (subCols) {
        for (const subCol of subCols) {
          const singleCol = subCol;
          const colId = singleCol.id;
          if (colId) {
            result[colId] = newVisibilityStatus;
          }
        }
      } else if (matchingCol.parent) {
        // update parent group state if necessary so it's consistent
        const matchingId = matchingCol.id;
        if (matchingId) {
          const parentGroup = matchingCol.parent;

          if (parentGroup && parentGroup.columns) {
            const checkedState = getCheckedStateOfColumnGroup(
              parentGroup.columns,
              result,
            );
            const parentId = parentGroup.id;
            if (parentId && checkedState !== 'indeterminate') {
              result[parentId] = checkedState === false ? 'hidden' : 'visible';
            }
          }
        }
      }
    }
  }
  return result;
}

/**
 * Gets checked state for SingleColumn and ColumnGroup. SingleColumn
 * is simply the entry value, but for ColumnGroup we need to check
 * the sub-columns to see if it is indeterminate.
 * @param col - table column for which you want the checked state
 * @param columnVisibility - all column visibility information
 *
 * @returns true, false or 'indeterminate'
 */
export function getCheckedState(
  col: ColumnMinInstance,
  columnVisibility: ColumnVisibilityConfig,
): boolean | 'indeterminate' {
  const colGroup = col;
  if (colGroup && colGroup.columns) {
    return getCheckedStateOfColumnGroup(colGroup.columns, columnVisibility);
  } else {
    // otherwise, single column is simple to determine:
    const idOrAccessor = col.id;
    const value = columnVisibility[idOrAccessor];
    return value === 'visible';
  }
}

/**
 * Given the columns in a column group, determines what checked state
 * the group has.
 * @param columns - columns of column group
 * @param columnVisibility - all visibility info
 *
 * @returns 'indeterminate' if columns are mixed visible/hidden, true if
 *          all columns are visible, false if all columns are hidden
 */
function getCheckedStateOfColumnGroup(
  columns: ColumnMinInstance[],
  columnVisibility: ColumnVisibilityConfig,
): boolean | 'indeterminate' {
  // check for 'indeterminate' state for column group (sub-cols are mixed 'visible' / 'hidden')
  let lastOne: 'visible' | 'hidden' | undefined = undefined;

  for (const current of columns) {
    const idOrAccessor = current.id;
    if (idOrAccessor) {
      const visibility = columnVisibility[idOrAccessor];
      if (lastOne === undefined) {
        lastOne = visibility;
      } else if (lastOne !== visibility) {
        return 'indeterminate';
      }
    }
  }
  if (lastOne === 'visible') {
    return true;
  }
  return false;
}

/**
 * Checks if entries are all true, all false or mixed and returns appropriate value.
 * @param columnVisibility - column visibility info
 *
 * @returns 'indeterminate' if visibility is mixed visible/hidden, true if
 *          all entries are visible, false if all entries are hidden
 */
export function getStateOfAll(
  columnVisibilityEntries: [string, 'visible' | 'hidden'][],
): boolean | 'indeterminate' {
  if (columnVisibilityEntries.length === 0) {
    return false;
  }

  const oneEntry = columnVisibilityEntries[0];
  let result: boolean | 'indeterminate' = oneEntry[1] === 'visible';
  for (const currentEntry of columnVisibilityEntries) {
    const value = currentEntry[1];
    const currentChecked = value === 'visible';
    if (currentChecked !== result) {
      result = 'indeterminate';
      break;
    }
  }
  return result;
}

/**
 * Creates onChange callback for checkbox.
 * @param columnVisibility -
 * @param onVisibilityChange -
 *
 * @returns
 */
export function createCheckboxOnChange(
  columns: ColumnMinInstance[],
  columnVisibility: ColumnVisibilityConfig,
  onVisibilityChange: (visibility: ColumnVisibilityConfig) => void,
) {
  return (accessor: string, checked: boolean) => {
    const updatedVisibility = getUpdatedVisibility(
      columnVisibility,
      checked ? 'visible' : 'hidden',
      columns,
      accessor,
    );

    onVisibilityChange(updatedVisibility);
  };
}

/**
 * Convenience function for creating a default visibility object from column
 * definitions. All columns are added to the object and by default all are
 * set to 'visible'.
 * @param columns - table columns passed to DataTable.
 *
 * @returns default visibility settings.
 */
export function createDefaultVisibilityObjectForColumns(
  columns: TableColumn[],
): ColumnVisibilityConfig {
  const result: ColumnVisibilityConfig = {};
  for (const col of columns) {
    // if there is no string id or accessor, an error is thrown
    const idOrAccessor = getIdOrStringAccessor(col);
    if (getIsExcludableColumn(idOrAccessor)) {
      continue;
    }
    if (idOrAccessor) {
      result[idOrAccessor] = 'visible';
    }

    const colGroup = col as ColumnGroup;
    if (colGroup.columns) {
      const subColsResult = createDefaultVisibilityObjectForColumns(
        colGroup.columns,
      );
      Object.assign(result, subColsResult);
    }
  }

  return result;
}
